20. 
21. /// Idempotence: re-mapping an already-reachable page (when the mapper is live)
22. /// leaves the abstract state unchanged. Backs the caller expectation that
23. /// `identity_map_page` is a safe no-op on an already-mapped page (e.g. per page
24. /// in a range).
25. pub proof fn lemma_map_idempotent(v: IdentityMapView, frame: nat)
26.     requires
27.         v.initialized,
28.         v.mapped.contains(frame),
29.     ensures
30.         v.spec_identity_map_page(frame) =~= v,
31. {
32.     assert(v.mapped.insert(frame) =~= v.mapped);
33. }
34. 
35. /// Map-on-success: after mapping the page covering `phys_addr` on a live mapper,
36. /// that address is reachable. Backs `identity_map_page`'s / `ensure_pte`'s
37. /// success postcondition (`maps(phys_addr)`).
38. pub proof fn lemma_map_on_success(v: IdentityMapView, phys_addr: int)
39.     requires
40.         v.initialized,
41.         phys_addr >= 0,
42.         spec_page_size() > 0,
43.     ensures
44.         v.spec_identity_map_page((phys_addr / spec_page_size()) as nat).maps(phys_addr),
45. {
46.     let frame = (phys_addr / spec_page_size()) as nat;
47.     assert(v.spec_identity_map_page(frame).mapped =~= v.mapped.insert(frame));
48.     assert(v.mapped.insert(frame).contains(frame));
49. }
50. 
51. /// Monotone growth: mapping a page never removes any previously reachable page
52. /// and never flips the lifecycle flag. Backs the "mappings are never torn down"
53. /// invariant the range loop in `ensure_identity_mapped_range` relies on.
54. pub proof fn lemma_map_monotone(v: IdentityMapView, frame: nat)
55.     ensures
56.         v.mapped.subset_of(v.spec_identity_map_page(frame).mapped),
57.         v.spec_identity_map_page(frame).initialized == v.initialized,
58. {
59.     let post = v.spec_identity_map_page(frame);
60.     assert(v.mapped.subset_of(post.mapped)) by {
61.         if v.initialized {
62.             assert(post.mapped =~= v.mapped.insert(frame));
63.         } else {
64.             assert(post.mapped =~= v.mapped);
65.         }
66.     }
67. }
68. 
69. /// Invariant preservation: mapping an in-range frame keeps every recorded frame
70. /// valid. Backs the all-or-nothing guarantee -- a successful mapping never
71. /// records an out-of-range frame.
72. pub proof fn lemma_map_preserves_inv(v: IdentityMapView, frame: nat)
73.     requires
74.         v.inv(),
75.         frame < IdentityMapView::max_frames(),
76.     ensures
77.         v.spec_identity_map_page(frame).inv(),
78. {
79.     let post = v.spec_identity_map_page(frame);
80.     assert forall|f: nat| #[trigger] post.mapped.contains(f) implies f < IdentityMapView::max_frames() by {
81.         if v.initialized {
82.             assert(post.mapped =~= v.mapped.insert(frame));
83.             if f != frame {
84.                 assert(v.mapped.contains(f));
85.             }
86.         } else {
87.             assert(v.mapped.contains(f));
88.         }
89.     }
90. }
91. 
